{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "@neriousy/opencode-browser",
  "version": "0.5.0",
  "description": "An Electron browser surface for the OpenCode v2 TUI",
  "keywords": [
    "opencode",
    "tui",
    "browser",
    "electron",
    "mcp",
    "opentui"
  ],
  "packageManager": "bun@1.3.14",
  "homepage": "https://github.com/neriousy/opencode-browser#readme",
  "author": "neriousy",
  "bugs": {
    "url": "https://github.com/neriousy/opencode-browser/issues"
  },
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/neriousy/opencode-browser.git"
  },
  "bin": {
    "opencode-browser-controller-mcp": "dist/controller-mcp.js"
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "type": "module",
  "exports": {
    "./tui": {
      "types": "./dist/tui.d.ts",
      "import": "./dist/tui.js"
    }
  },
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "build": "bun scripts/build.ts",
    "typecheck": "tsc --noEmit",
    "test": "bun test",
    "test:mcp": "bun scripts/smoke-devtools-mcp.ts",
    "format": "oxfmt .",
    "format:check": "oxfmt --check .",
    "check": "bun run format:check && bun run typecheck && bun test && bun run build",
    "test:packed": "bun run build && bun scripts/test-packed.ts",
    "prepack": "bun run check"
  },
  "dependencies": {
    "@modelcontextprotocol/sdk": "1.30.0",
    "chrome-devtools-mcp": "1.6.0",
    "effect": "4.0.0-beta.101",
    "electron": "43.2.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "0.0.0-next-16650",
    "@opencode-ai/theme": "0.0.0-next-16650",
    "@opentui/core": "0.4.5",
    "@opentui/keymap": "0.4.5",
    "@opentui/solid": "0.4.5",
    "@types/bun": "latest",
    "@types/node": "^24.0.0",
    "opentui-browser": "0.3.2",
    "oxfmt": "0.41.0",
    "solid-js": "1.9.12",
    "typescript": "^5"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=0.0.0-next-16650 <0.1.0",
    "@opentui/core": "^0.4.5",
    "@opentui/keymap": "^0.4.5",
    "@opentui/solid": "^0.4.5",
    "solid-js": ">=1.9.10 <2"
  },
  "peerDependenciesMeta": {
    "@opencode-ai/plugin": {
      "optional": true
    },
    "@opentui/core": {
      "optional": true
    },
    "@opentui/keymap": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    }
  },
  "engines": {
    "bun": ">=1.3.0",
    "node": ">=22.12.0"
  }
}
